            new Blog(
                new LocalizedText("Implementing Clean Architecture in .NET", "Implémenter Clean Architecture dans .NET"),
                new LocalizedText("Learn how to structure your .NET applications using Clean Architecture principles for maintainability and testability.", 
                                 "Apprenez à structurer vos applications .NET en utilisant les principes de Clean Architecture pour la maintenabilité et la testabilité."),
                new LocalizedText("# Implementing Clean Architecture in .NET\n\nClean Architecture, popularized by Robert C. Martin (Uncle Bob), provides a way to structure applications that are independent of frameworks, databases, and external concerns.\n\n## Core Principles\n\n1. **Independence**: The architecture doesn't depend on external libraries\n2. **Testability**: Business rules can be tested without UI, database, or web server\n3. **UI Independence**: UI can change without changing business rules\n4. **Database Independence**: Business rules aren't bound to the database\n5. **External Agency Independence**: Business rules don't know about external interfaces\n\n## Layer Structure\n\n### 1. Domain Layer (Core)\n\n```csharp\n// Entities\npublic class Blog : BaseEntity\n{\n    public string Title { get; private set; }\n    public string Content { get; private set; }\n    public DateTime PublishedAt { get; private set; }\n    public Author Author { get; private set; }\n    \n    private Blog() { } // EF Core\n    \n    public Blog(string title, string content, Author author)\n    {\n        Title = title ?? throw new ArgumentNullException(nameof(title));\n        Content = content ?? throw new ArgumentNullException(nameof(content));\n        Author = author ?? throw new ArgumentNullException(nameof(author));\n        CreatedAt = DateTime.UtcNow;\n    }\n    \n    public void Publish()\n    {\n        if (string.IsNullOrWhiteSpace(Title))\n            throw new InvalidOperationException(\"Cannot publish blog without title\");\n            \n        PublishedAt = DateTime.UtcNow;\n        IsPublished = true;\n    }\n}\n\n// Value Objects\npublic class Email\n{\n    public string Value { get; private set; }\n    \n    public Email(string value)\n    {\n        if (string.IsNullOrWhiteSpace(value))\n            throw new ArgumentException(\"Email cannot be empty\");\n        if (!IsValidEmail(value))\n            throw new ArgumentException(\"Invalid email format\");\n            \n        Value = value;\n    }\n    \n    private static bool IsValidEmail(string email)\n    {\n        return Regex.IsMatch(email, @\"^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$\");\n    }\n}\n\n// Domain Events\npublic class BlogPublishedEvent : IDomainEvent\n{\n    public Blog Blog { get; }\n    public DateTime OccurredAt { get; }\n    \n    public BlogPublishedEvent(Blog blog)\n    {\n        Blog = blog;\n        OccurredAt = DateTime.UtcNow;\n    }\n}\n```\n\n### 2. Application Layer\n\n```csharp\n// Use Cases / Commands\npublic class CreateBlogCommand : IRequest<BlogDto>\n{\n    public string Title { get; set; }\n    public string Content { get; set; }\n    public int AuthorId { get; set; }\n}\n\npublic class CreateBlogCommandHandler : IRequestHandler<CreateBlogCommand, BlogDto>\n{\n    private readonly IBlogRepository _blogRepository;\n    private readonly IAuthorRepository _authorRepository;\n    private readonly IUnitOfWork _unitOfWork;\n    \n    public CreateBlogCommandHandler(\n        IBlogRepository blogRepository,\n        IAuthorRepository authorRepository,\n        IUnitOfWork unitOfWork)\n    {\n        _blogRepository = blogRepository;\n        _authorRepository = authorRepository;\n        _unitOfWork = unitOfWork;\n    }\n    \n    public async Task<BlogDto> Handle(CreateBlogCommand request, CancellationToken cancellationToken)\n    {\n        var author = await _authorRepository.GetByIdAsync(request.AuthorId);\n        if (author == null)\n            throw new NotFoundException(\"Author not found\");\n        \n        var blog = new Blog(request.Title, request.Content, author);\n        \n        await _blogRepository.AddAsync(blog);\n        await _unitOfWork.SaveChangesAsync(cancellationToken);\n        \n        return new BlogDto\n        {\n            Id = blog.Id,\n            Title = blog.Title,\n            Content = blog.Content,\n            AuthorName = blog.Author.Name\n        };\n    }\n}\n\n// Interfaces\npublic interface IBlogRepository\n{\n    Task<Blog> GetByIdAsync(int id);\n    Task<IEnumerable<Blog>> GetPublishedBlogsAsync();\n    Task AddAsync(Blog blog);\n    Task UpdateAsync(Blog blog);\n    Task DeleteAsync(Blog blog);\n}\n\npublic interface IUnitOfWork\n{\n    Task<int> SaveChangesAsync(CancellationToken cancellationToken = default);\n}\n```\n\n### 3. Infrastructure Layer\n\n```csharp\n// Repository Implementation\npublic class BlogRepository : IBlogRepository\n{\n    private readonly AppDbContext _context;\n    \n    public BlogRepository(AppDbContext context)\n    {\n        _context = context;\n    }\n    \n    public async Task<Blog> GetByIdAsync(int id)\n    {\n        return await _context.Blogs\n            .Include(b => b.Author)\n            .FirstOrDefaultAsync(b => b.Id == id);\n    }\n    \n    public async Task<IEnumerable<Blog>> GetPublishedBlogsAsync()\n    {\n        return await _context.Blogs\n            .Where(b => b.IsPublished)\n            .Include(b => b.Author)\n            .OrderByDescending(b => b.PublishedAt)\n            .ToListAsync();\n    }\n    \n    public async Task AddAsync(Blog blog)\n    {\n        await _context.Blogs.AddAsync(blog);\n    }\n    \n    public Task UpdateAsync(Blog blog)\n    {\n        _context.Blogs.Update(blog);\n        return Task.CompletedTask;\n    }\n    \n    public Task DeleteAsync(Blog blog)\n    {\n        _context.Blogs.Remove(blog);\n        return Task.CompletedTask;\n    }\n}\n\n// Unit of Work Implementation\npublic class UnitOfWork : IUnitOfWork\n{\n    private readonly AppDbContext _context;\n    \n    public UnitOfWork(AppDbContext context)\n    {\n        _context = context;\n    }\n    \n    public async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)\n    {\n        return await _context.SaveChangesAsync(cancellationToken);\n    }\n}\n```\n\n### 4. Presentation Layer\n\n```csharp\n[ApiController]\n[Route(\"api/[controller]\")]\npublic class BlogsController : ControllerBase\n{\n    private readonly IMediator _mediator;\n    \n    public BlogsController(IMediator mediator)\n    {\n        _mediator = mediator;\n    }\n    \n    [HttpGet]\n    public async Task<ActionResult<IEnumerable<BlogDto>>> GetBlogs()\n    {\n        var blogs = await _mediator.Send(new GetPublishedBlogsQuery());\n        return Ok(blogs);\n    }\n    \n    [HttpPost]\n    public async Task<ActionResult<BlogDto>> CreateBlog(CreateBlogCommand command)\n    {\n        var blog = await _mediator.Send(command);\n        return CreatedAtAction(nameof(GetBlog), new { id = blog.Id }, blog);\n    }\n    \n    [HttpGet(\"{id}\")]\n    public async Task<ActionResult<BlogDto>> GetBlog(int id)\n    {\n        var blog = await _mediator.Send(new GetBlogByIdQuery { Id = id });\n        return blog != null ? Ok(blog) : NotFound();\n    }\n}\n```\n\n## Dependency Injection Setup\n\n```csharp\n// Program.cs\nvar builder = WebApplication.CreateBuilder(args);\n\n// Domain Services\nbuilder.Services.AddScoped<IBlogRepository, BlogRepository>();\nbuilder.Services.AddScoped<IAuthorRepository, AuthorRepository>();\nbuilder.Services.AddScoped<IUnitOfWork, UnitOfWork>();\n\n// Application Services\nbuilder.Services.AddMediatR(typeof(CreateBlogCommandHandler));\nbuilder.Services.AddAutoMapper(typeof(BlogMappingProfile));\n\n// Infrastructure\nbuilder.Services.AddDbContext<AppDbContext>(options =>\n    options.UseSqlServer(builder.Configuration.GetConnectionString(\"DefaultConnection\")));\n\nvar app = builder.Build();\n```\n\n## Testing Strategy\n\n```csharp\n// Unit Test Example\npublic class CreateBlogCommandHandlerTests\n{\n    private readonly Mock<IBlogRepository> _blogRepositoryMock;\n    private readonly Mock<IAuthorRepository> _authorRepositoryMock;\n    private readonly Mock<IUnitOfWork> _unitOfWorkMock;\n    private readonly CreateBlogCommandHandler _handler;\n    \n    public CreateBlogCommandHandlerTests()\n    {\n        _blogRepositoryMock = new Mock<IBlogRepository>();\n        _authorRepositoryMock = new Mock<IAuthorRepository>();\n        _unitOfWorkMock = new Mock<IUnitOfWork>();\n        _handler = new CreateBlogCommandHandler(\n            _blogRepositoryMock.Object,\n            _authorRepositoryMock.Object,\n            _unitOfWorkMock.Object);\n    }\n    \n    [Fact]\n    public async Task Handle_ValidCommand_ShouldCreateBlog()\n    {\n        // Arrange\n        var author = new Author(\"John Doe\", \"john@example.com\");\n        var command = new CreateBlogCommand\n        {\n            Title = \"Test Blog\",\n            Content = \"Test Content\",\n            AuthorId = 1\n        };\n        \n        _authorRepositoryMock.Setup(x => x.GetByIdAsync(1))\n            .ReturnsAsync(author);\n        \n        // Act\n        var result = await _handler.Handle(command, CancellationToken.None);\n        \n        // Assert\n        Assert.NotNull(result);\n        Assert.Equal(command.Title, result.Title);\n        _blogRepositoryMock.Verify(x => x.AddAsync(It.IsAny<Blog>()), Times.Once);\n        _unitOfWorkMock.Verify(x => x.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);\n    }\n}\n```\n\n## Benefits\n\n1. **Maintainability**: Clear separation of concerns\n2. **Testability**: Easy to unit test business logic\n3. **Flexibility**: Easy to change external dependencies\n4. **Scalability**: Well-organized code that's easy to extend\n5. **Independence**: Core business logic doesn't depend on frameworks\n\n## Common Pitfalls\n\n1. **Over-engineering**: Don't use Clean Architecture for simple CRUD apps\n2. **Anemic Domain Model**: Ensure your domain objects have behavior\n3. **Too many layers**: Keep it simple, don't add unnecessary abstraction\n4. **Ignoring performance**: Consider the cost of multiple layers\n\nClean Architecture is powerful for complex domains but may be overkill for simple applications. Choose the right tool for the job.",
                                 "# Implémenter Clean Architecture dans .NET\n\nClean Architecture, popularisée par Robert C. Martin (Uncle Bob), fournit une façon de structurer les applications qui sont indépendantes des frameworks, des bases de données et des préoccupations externes.\n\n## Principes fondamentaux\n\n1. **Indépendance** : L'architecture ne dépend pas de bibliothèques externes\n2. **Testabilité** : Les règles métier peuvent être testées sans UI, base de données ou serveur web\n3. **Indépendance de l'UI** : L'UI peut changer sans modifier les règles métier\n4. **Indépendance de la base de données** : Les règles métier ne sont pas liées à la base de données\n5. **Indépendance des agences externes** : Les règles métier ne connaissent pas les interfaces externes\n\n## Structure des couches\n\n### 1. Couche Domain (Core)\n\n```csharp\n// Entités\npublic class Blog : BaseEntity\n{\n    public string Title { get; private set; }\n    public string Content { get; private set; }\n    public DateTime PublishedAt { get; private set; }\n    public Author Author { get; private set; }\n    \n    private Blog() { } // EF Core\n    \n    public Blog(string title, string content, Author author)\n    {\n        Title = title ?? throw new ArgumentNullException(nameof(title));\n        Content = content ?? throw new ArgumentNullException(nameof(content));\n        Author = author ?? throw new ArgumentNullException(nameof(author));\n        CreatedAt = DateTime.UtcNow;\n    }\n    \n    public void Publish()\n    {\n        if (string.IsNullOrWhiteSpace(Title))\n            throw new InvalidOperationException(\"Impossible de publier un blog sans titre\");\n            \n        PublishedAt = DateTime.UtcNow;\n        IsPublished = true;\n    }\n}\n\n// Objets de valeur\npublic class Email\n{\n    public string Value { get; private set; }\n    \n    public Email(string value)\n    {\n        if (string.IsNullOrWhiteSpace(value))\n            throw new ArgumentException(\"L'email ne peut pas être vide\");\n        if (!IsValidEmail(value))\n            throw new ArgumentException(\"Format d'email invalide\");\n            \n        Value = value;\n    }\n    \n    private static bool IsValidEmail(string email)\n    {\n        return Regex.IsMatch(email, @\"^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$\");\n    }\n}\n\n// Événements de domaine\npublic class BlogPublishedEvent : IDomainEvent\n{\n    public Blog Blog { get; }\n    public DateTime OccurredAt { get; }\n    \n    public BlogPublishedEvent(Blog blog)\n    {\n        Blog = blog;\n        OccurredAt = DateTime.UtcNow;\n    }\n}\n```\n\n### 2. Couche Application\n\n```csharp\n// Cas d'utilisation / Commandes\npublic class CreateBlogCommand : IRequest<BlogDto>\n{\n    public string Title { get; set; }\n    public string Content { get; set; }\n    public int AuthorId { get; set; }\n}\n\npublic class CreateBlogCommandHandler : IRequestHandler<CreateBlogCommand, BlogDto>\n{\n    private readonly IBlogRepository _blogRepository;\n    private readonly IAuthorRepository _authorRepository;\n    private readonly IUnitOfWork _unitOfWork;\n    \n    public CreateBlogCommandHandler(\n        IBlogRepository blogRepository,\n        IAuthorRepository authorRepository,\n        IUnitOfWork unitOfWork)\n    {\n        _blogRepository = blogRepository;\n        _authorRepository = authorRepository;\n        _unitOfWork = unitOfWork;\n    }\n    \n    public async Task<BlogDto> Handle(CreateBlogCommand request, CancellationToken cancellationToken)\n    {\n        var author = await _authorRepository.GetByIdAsync(request.AuthorId);\n        if (author == null)\n            throw new NotFoundException(\"Auteur introuvable\");\n        \n        var blog = new Blog(request.Title, request.Content, author);\n        \n        await _blogRepository.AddAsync(blog);\n        await _unitOfWork.SaveChangesAsync(cancellationToken);\n        \n        return new BlogDto\n        {\n            Id = blog.Id,\n            Title = blog.Title,\n            Content = blog.Content,\n            AuthorName = blog.Author.Name\n        };\n    }\n}\n\n// Interfaces\npublic interface IBlogRepository\n{\n    Task<Blog> GetByIdAsync(int id);\n    Task<IEnumerable<Blog>> GetPublishedBlogsAsync();\n    Task AddAsync(Blog blog);\n    Task UpdateAsync(Blog blog);\n    Task DeleteAsync(Blog blog);\n}\n\npublic interface IUnitOfWork\n{\n    Task<int> SaveChangesAsync(CancellationToken cancellationToken = default);\n}\n```\n\n### 3. Couche Infrastructure\n\n```csharp\n// Implémentation du Repository\npublic class BlogRepository : IBlogRepository\n{\n    private readonly AppDbContext _context;\n    \n    public BlogRepository(AppDbContext context)\n    {\n        _context = context;\n    }\n    \n    public async Task<Blog> GetByIdAsync(int id)\n    {\n        return await _context.Blogs\n            .Include(b => b.Author)\n            .FirstOrDefaultAsync(b => b.Id == id);\n    }\n    \n    public async Task<IEnumerable<Blog>> GetPublishedBlogsAsync()\n    {\n        return await _context.Blogs\n            .Where(b => b.IsPublished)\n            .Include(b => b.Author)\n            .OrderByDescending(b => b.PublishedAt)\n            .ToListAsync();\n    }\n    \n    public async Task AddAsync(Blog blog)\n    {\n        await _context.Blogs.AddAsync(blog);\n    }\n    \n    public Task UpdateAsync(Blog blog)\n    {\n        _context.Blogs.Update(blog);\n        return Task.CompletedTask;\n    }\n    \n    public Task DeleteAsync(Blog blog)\n    {\n        _context.Blogs.Remove(blog);\n        return Task.CompletedTask;\n    }\n}\n\n// Implémentation Unit of Work\npublic class UnitOfWork : IUnitOfWork\n{\n    private readonly AppDbContext _context;\n    \n    public UnitOfWork(AppDbContext context)\n    {\n        _context = context;\n    }\n    \n    public async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)\n    {\n        return await _context.SaveChangesAsync(cancellationToken);\n    }\n}\n```\n\n### 4. Couche Presentation\n\n```csharp\n[ApiController]\n[Route(\"api/[controller]\")]\npublic class BlogsController : ControllerBase\n{\n    private readonly IMediator _mediator;\n    \n    public BlogsController(IMediator mediator)\n    {\n        _mediator = mediator;\n    }\n    \n    [HttpGet]\n    public async Task<ActionResult<IEnumerable<BlogDto>>> GetBlogs()\n    {\n        var blogs = await _mediator.Send(new GetPublishedBlogsQuery());\n        return Ok(blogs);\n    }\n    \n    [HttpPost]\n    public async Task<ActionResult<BlogDto>> CreateBlog(CreateBlogCommand command)\n    {\n        var blog = await _mediator.Send(command);\n        return CreatedAtAction(nameof(GetBlog), new { id = blog.Id }, blog);\n    }\n    \n    [HttpGet(\"{id}\")]\n    public async Task<ActionResult<BlogDto>> GetBlog(int id)\n    {\n        var blog = await _mediator.Send(new GetBlogByIdQuery { Id = id });\n        return blog != null ? Ok(blog) : NotFound();\n    }\n}\n```\n\n## Configuration de l'injection de dépendances\n\n```csharp\n// Program.cs\nvar builder = WebApplication.CreateBuilder(args);\n\n// Services de domaine\nbuilder.Services.AddScoped<IBlogRepository, BlogRepository>();\nbuilder.Services.AddScoped<IAuthorRepository, AuthorRepository>();\nbuilder.Services.AddScoped<IUnitOfWork, UnitOfWork>();\n\n// Services d'application\nbuilder.Services.AddMediatR(typeof(CreateBlogCommandHandler));\nbuilder.Services.AddAutoMapper(typeof(BlogMappingProfile));\n\n// Infrastructure\nbuilder.Services.AddDbContext<AppDbContext>(options =>\n    options.UseSqlServer(builder.Configuration.GetConnectionString(\"DefaultConnection\")));\n\nvar app = builder.Build();\n```\n\n## Stratégie de tests\n\n```csharp\n// Exemple de test unitaire\npublic class CreateBlogCommandHandlerTests\n{\n    private readonly Mock<IBlogRepository> _blogRepositoryMock;\n    private readonly Mock<IAuthorRepository> _authorRepositoryMock;\n    private readonly Mock<IUnitOfWork> _unitOfWorkMock;\n    private readonly CreateBlogCommandHandler _handler;\n    \n    public CreateBlogCommandHandlerTests()\n    {\n        _blogRepositoryMock = new Mock<IBlogRepository>();\n        _authorRepositoryMock = new Mock<IAuthorRepository>();\n        _unitOfWorkMock = new Mock<IUnitOfWork>();\n        _handler = new CreateBlogCommandHandler(\n            _blogRepositoryMock.Object,\n            _authorRepositoryMock.Object,\n            _unitOfWorkMock.Object);\n    }\n    \n    [Fact]\n    public async Task Handle_ValidCommand_ShouldCreateBlog()\n    {\n        // Arrange\n        var author = new Author(\"John Doe\", \"john@example.com\");\n        var command = new CreateBlogCommand\n        {\n            Title = \"Blog de test\",\n            Content = \"Contenu de test\",\n            AuthorId = 1\n        };\n        \n        _authorRepositoryMock.Setup(x => x.GetByIdAsync(1))\n            .ReturnsAsync(author);\n        \n        // Act\n        var result = await _handler.Handle(command, CancellationToken.None);\n        \n        // Assert\n        Assert.NotNull(result);\n        Assert.Equal(command.Title, result.Title);\n        _blogRepositoryMock.Verify(x => x.AddAsync(It.IsAny<Blog>()), Times.Once);\n        _unitOfWorkMock.Verify(x => x.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);\n    }\n}\n```\n\n## Avantages\n\n1. **Maintenabilité** : Séparation claire des préoccupations\n2. **Testabilité** : Facile de tester unitairement la logique métier\n3. **Flexibilité** : Facile de changer les dépendances externes\n4. **Évolutivité** : Code bien organisé et facile à étendre\n5. **Indépendance** : La logique métier centrale ne dépend pas des frameworks\n\n## Pièges courants\n\n1. **Sur-ingénierie** : N'utilisez pas Clean Architecture pour des applications CRUD simples\n2. **Modèle de domaine anémique** : Assurez-vous que vos objets de domaine ont des comportements\n3. **Trop de couches** : Restez simple, n'ajoutez pas d'abstraction inutile\n4. **Ignorer les performances** : Considérez le coût de plusieurs couches\n\nClean Architecture est puissante pour les domaines complexes mais peut être excessive pour les applications simples. Choisissez le bon outil pour le travail."),
