                new LocalizedText("# Advanced C# Features You Should Know\n\nC# continues to evolve with each release, introducing powerful features that can significantly improve your code quality and developer productivity. Let's explore some advanced features that every C# developer should master.\n\n## Pattern Matching\n\n### Switch Expressions (C# 8.0+)\n\n```csharp\n// Traditional switch statement\nstatic string GetSeasonTraditional(int month)\n{\n    switch (month)\n    {\n        case 12:\n        case 1:\n        case 2:\n            return \"Winter\";\n        case 3:\n        case 4:\n        case 5:\n            return \"Spring\";\n        case 6:\n        case 7:\n        case 8:\n            return \"Summer\";\n        case 9:\n        case 10:\n        case 11:\n            return \"Fall\";\n        default:\n            return \"Unknown\";\n    }\n}\n\n// Modern switch expression\nstatic string GetSeason(int month) => month switch\n{\n    12 or 1 or 2 => \"Winter\",\n    3 or 4 or 5 => \"Spring\",\n    6 or 7 or 8 => \"Summer\",\n    9 or 10 or 11 => \"Fall\",\n    _ => \"Unknown\"\n};\n```\n\n### Property Patterns\n\n```csharp\npublic static string AnalyzeObject(object obj) => obj switch\n{\n    string { Length: > 10 } => \"Long string\",\n    string { Length: <= 10 } => \"Short string\",\n    int value when value > 0 => \"Positive integer\",\n    int value when value < 0 => \"Negative integer\",\n    Person { Age: >= 18, Name: not null } => \"Adult with name\",\n    Person { Age: < 18 } => \"Minor\",\n    null => \"Null object\",\n    _ => \"Unknown type\"\n};\n```\n\n## Records (C# 9.0+)\n\n### Immutable Data Models\n\n```csharp\n// Traditional class\npublic class PersonClass\n{\n    public string FirstName { get; set; }\n    public string LastName { get; set; }\n    \n    public override bool Equals(object obj) { /* implementation */ }\n    public override int GetHashCode() { /* implementation */ }\n    public override string ToString() { /* implementation */ }\n}\n\n// Record - automatic equality, hashing, and string representation\npublic record Person(string FirstName, string LastName)\n{\n    public string FullName => $\"{FirstName} {LastName}\";\n}\n\n// Usage\nvar person1 = new Person(\"John\", \"Doe\");\nvar person2 = new Person(\"John\", \"Doe\");\nvar person3 = person1 with { LastName = \"Smith\" }; // Non-destructive mutation\n\nConsole.WriteLine(person1 == person2); // True\nConsole.WriteLine(person1); // Person { FirstName = John, LastName = Doe }\n```\n\n### Record Inheritance\n\n```csharp\npublic record Vehicle(string Make, string Model, int Year);\npublic record Car(string Make, string Model, int Year, int Doors) : Vehicle(Make, Model, Year);\npublic record Motorcycle(string Make, string Model, int Year, bool HasSidecar) : Vehicle(Make, Model, Year);\n```\n\n## Nullable Reference Types (C# 8.0+)\n\n```csharp\n// Enable nullable reference types\n#nullable enable\n\npublic class UserService\n{\n    private readonly ILogger<UserService> _logger;\n    \n    public UserService(ILogger<UserService> logger)\n    {\n        _logger = logger ?? throw new ArgumentNullException(nameof(logger));\n    }\n    \n    // Method clearly indicates it can return null\n    public User? FindUser(int id)\n    {\n        return id > 0 ? new User(id, \"John Doe\") : null;\n    }\n    \n    // Method guarantees non-null return\n    public User GetUserOrDefault(int id)\n    {\n        return FindUser(id) ?? new User(0, \"Unknown\");\n    }\n    \n    public void ProcessUser(User user) // user is guaranteed to be non-null\n    {\n        // No null check needed - compiler ensures user is not null\n        _logger.LogInformation(\"Processing user: {UserName}\", user.Name);\n    }\n}\n```\n\n## Async Streams (C# 8.0+)\n\n```csharp\npublic static async IAsyncEnumerable<int> GenerateNumbersAsync(\n    int count,\n    [EnumeratorCancellation] CancellationToken cancellationToken = default)\n{\n    for (int i = 0; i < count; i++)\n    {\n        cancellationToken.ThrowIfCancellationRequested();\n        \n        await Task.Delay(100, cancellationToken); // Simulate async work\n        yield return i;\n    }\n}\n\n// Usage\nvar cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));\n\nawait foreach (var number in GenerateNumbersAsync(100, cts.Token))\n{\n    Console.WriteLine(number);\n}\n```\n\n## Init-Only Properties (C# 9.0+)\n\n```csharp\npublic class ImmutablePerson\n{\n    public string FirstName { get; init; } = string.Empty;\n    public string LastName { get; init; } = string.Empty;\n    public DateTime BirthDate { get; init; }\n    \n    public int Age => DateTime.Now.Year - BirthDate.Year;\n}\n\n// Usage\nvar person = new ImmutablePerson\n{\n    FirstName = \"John\",\n    LastName = \"Doe\",\n    BirthDate = new DateTime(1990, 1, 1)\n};\n\n// person.FirstName = \"Jane\"; // Compilation error - property is init-only\n```\n\n## Global Using Directives (C# 10.0+)\n\n```csharp\n// GlobalUsings.cs\nglobal using System;\nglobal using System.Collections.Generic;\nglobal using System.Linq;\nglobal using System.Threading.Tasks;\nglobal using Microsoft.Extensions.Logging;\nglobal using MyApp.Common.Extensions;\n\n// Now these usings are available in all files in the project\n```\n\n## File-Scoped Namespaces (C# 10.0+)\n\n```csharp\n// Traditional namespace\nnamespace MyApp.Services\n{\n    public class UserService\n    {\n        // Implementation\n    }\n}\n\n// File-scoped namespace (C# 10)\nnamespace MyApp.Services;\n\npublic class UserService\n{\n    // Implementation\n}\n```\n\n## Raw String Literals (C# 11.0+)\n\n```csharp\n// Traditional string with escape sequences\nstring json = \"{\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}\";\n\n// Verbatim string\nstring jsonVerbatim = @\"{\"\"name\"\": \"\"John\"\", \"\"age\"\": 30}\";\n\n// Raw string literal (C# 11)\nstring jsonRaw = \"\"\"\n                {\n                    \"name\": \"John\",\n                    \"age\": 30\n                }\n                \"\"\";\n\n// SQL example\nstring sql = \"\"\"\n            SELECT u.Name, u.Email, p.Title\n            FROM Users u\n            INNER JOIN Posts p ON u.Id = p.AuthorId\n            WHERE u.IsActive = 1\n            ORDER BY p.CreatedAt DESC\n            \"\"\";\n```\n\n## Required Members (C# 11.0+)\n\n```csharp\npublic class Person\n{\n    public required string FirstName { get; set; }\n    public required string LastName { get; set; }\n    public string? MiddleName { get; set; }\n    public int Age { get; set; }\n}\n\n// Usage\nvar person = new Person\n{\n    FirstName = \"John\",\n    LastName = \"Doe\",\n    Age = 30\n}; // MiddleName is optional\n\n// var invalidPerson = new Person { Age = 30 }; // Compilation error - FirstName and LastName are required\n```\n\n## List Patterns (C# 11.0+)\n\n```csharp\nstatic string CheckList(int[] numbers) => numbers switch\n{\n    [] => \"Empty list\",\n    [var single] => $\"Single item: {single}\",\n    [var first, var second] => $\"Two items: {first}, {second}\",\n    [var first, .., var last] => $\"Multiple items, first: {first}, last: {last}\",\n    [1, 2, 3] => \"Exactly 1, 2, 3\",\n    [1, .. var rest] => $\"Starts with 1, rest: [{string.Join(\", \", rest)}]\",\n    _ => \"Other pattern\"\n};\n```\n\n## Performance Tips\n\n### Use Span<T> for Memory-Efficient Operations\n\n```csharp\nstatic void ProcessLargeArray(int[] data)\n{\n    // Instead of creating subarrays, use Span<T>\n    var span = data.AsSpan();\n    var firstHalf = span[..(span.Length / 2)];\n    var secondHalf = span[(span.Length / 2)..];\n    \n    ProcessSpan(firstHalf);\n    ProcessSpan(secondHalf);\n}\n\nstatic void ProcessSpan(ReadOnlySpan<int> span)\n{\n    foreach (var item in span)\n    {\n        // Process without allocation\n    }\n}\n```\n\n### Use ValueTask for Performance-Critical Async Methods\n\n```csharp\npublic async ValueTask<User> GetUserAsync(int id)\n{\n    // If result is cached, return synchronously without Task allocation\n    if (_cache.TryGetValue(id, out var cachedUser))\n    {\n        return cachedUser;\n    }\n    \n    // Otherwise, perform async operation\n    var user = await _database.GetUserAsync(id);\n    _cache[id] = user;\n    return user;\n}\n```\n\n## Best Practices\n\n1. **Use pattern matching** to make code more readable and concise\n2. **Leverage records** for immutable data models\n3. **Enable nullable reference types** for better null safety\n4. **Use async streams** for processing large datasets\n5. **Prefer init-only properties** for immutable objects\n6. **Use raw string literals** for complex string content\n7. **Mark required members** to ensure proper initialization\n8. **Consider performance implications** of new features\n\nThese advanced features can significantly improve your code quality, but remember to use them judiciously based on your specific use cases and team preferences.",
                                 "# Fonctionnalités avancées de C# que vous devriez connaître\n\nC# continue d'évoluer avec chaque version, introduisant des fonctionnalités puissantes qui peuvent considérablement améliorer la qualité de votre code et la productivité des développeurs. Explorons quelques fonctionnalités avancées que chaque développeur C# devrait maîtriser.\n\n## Correspondance de motifs\n\n### Expressions Switch (C# 8.0+)\n\n```csharp\n// Instruction switch traditionnelle\nstatic string GetSeasonTraditional(int month)\n{\n    switch (month)\n    {\n        case 12:\n        case 1:\n        case 2:\n            return \"Hiver\";\n        case 3:\n        case 4:\n        case 5:\n            return \"Printemps\";\n        case 6:\n        case 7:\n        case 8:\n            return \"Été\";\n        case 9:\n        case 10:\n        case 11:\n            return \"Automne\";\n        default:\n            return \"Inconnu\";\n    }\n}\n\n// Expression switch moderne\nstatic string GetSeason(int month) => month switch\n{\n    12 or 1 or 2 => \"Hiver\",\n    3 or 4 or 5 => \"Printemps\",\n    6 or 7 or 8 => \"Été\",\n    9 or 10 or 11 => \"Automne\",\n    _ => \"Inconnu\"\n};\n```\n\n### Motifs de propriétés\n\n```csharp\npublic static string AnalyzeObject(object obj) => obj switch\n{\n    string { Length: > 10 } => \"Chaîne longue\",\n    string { Length: <= 10 } => \"Chaîne courte\",\n    int value when value > 0 => \"Entier positif\",\n    int value when value < 0 => \"Entier négatif\",\n    Person { Age: >= 18, Name: not null } => \"Adulte avec nom\",\n    Person { Age: < 18 } => \"Mineur\",\n    null => \"Objet null\",\n    _ => \"Type inconnu\"\n};\n```\n\n## Records (C# 9.0+)\n\n### Modèles de données immutables\n\n```csharp\n// Classe traditionnelle\npublic class PersonClass\n{\n    public string FirstName { get; set; }\n    public string LastName { get; set; }\n    \n    public override bool Equals(object obj) { /* implémentation */ }\n    public override int GetHashCode() { /* implémentation */ }\n    public override string ToString() { /* implémentation */ }\n}\n\n// Record - égalité, hachage et représentation chaîne automatiques\npublic record Person(string FirstName, string LastName)\n{\n    public string FullName => $\"{FirstName} {LastName}\";\n}\n\n// Usage\nvar person1 = new Person(\"John\", \"Doe\");\nvar person2 = new Person(\"John\", \"Doe\");\nvar person3 = person1 with { LastName = \"Smith\" }; // Mutation non-destructive\n\nConsole.WriteLine(person1 == person2); // True\nConsole.WriteLine(person1); // Person { FirstName = John, LastName = Doe }\n```\n\n### Héritage de Records\n\n```csharp\npublic record Vehicle(string Make, string Model, int Year);\npublic record Car(string Make, string Model, int Year, int Doors) : Vehicle(Make, Model, Year);\npublic record Motorcycle(string Make, string Model, int Year, bool HasSidecar) : Vehicle(Make, Model, Year);\n```\n\n## Types de référence nullable (C# 8.0+)\n\n```csharp\n// Activer les types de référence nullable\n#nullable enable\n\npublic class UserService\n{\n    private readonly ILogger<UserService> _logger;\n    \n    public UserService(ILogger<UserService> logger)\n    {\n        _logger = logger ?? throw new ArgumentNullException(nameof(logger));\n    }\n    \n    // La méthode indique clairement qu'elle peut retourner null\n    public User? FindUser(int id)\n    {\n        return id > 0 ? new User(id, \"John Doe\") : null;\n    }\n    \n    // La méthode garantit un retour non-null\n    public User GetUserOrDefault(int id)\n    {\n        return FindUser(id) ?? new User(0, \"Inconnu\");\n    }\n    \n    public void ProcessUser(User user) // user est garanti non-null\n    {\n        // Pas de vérification null nécessaire - le compilateur s'assure que user n'est pas null\n        _logger.LogInformation(\"Traitement utilisateur : {UserName}\", user.Name);\n    }\n}\n```\n\n## Flux asynchrones (C# 8.0+)\n\n```csharp\npublic static async IAsyncEnumerable<int> GenerateNumbersAsync(\n    int count,\n    [EnumeratorCancellation] CancellationToken cancellationToken = default)\n{\n    for (int i = 0; i < count; i++)\n    {\n        cancellationToken.ThrowIfCancellationRequested();\n        \n        await Task.Delay(100, cancellationToken); // Simuler du travail asynchrone\n        yield return i;\n    }\n}\n\n// Usage\nvar cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));\n\nawait foreach (var number in GenerateNumbersAsync(100, cts.Token))\n{\n    Console.WriteLine(number);\n}\n```\n\n## Propriétés Init-Only (C# 9.0+)\n\n```csharp\npublic class ImmutablePerson\n{\n    public string FirstName { get; init; } = string.Empty;\n    public string LastName { get; init; } = string.Empty;\n    public DateTime BirthDate { get; init; }\n    \n    public int Age => DateTime.Now.Year - BirthDate.Year;\n}\n\n// Usage\nvar person = new ImmutablePerson\n{\n    FirstName = \"John\",\n    LastName = \"Doe\",\n    BirthDate = new DateTime(1990, 1, 1)\n};\n\n// person.FirstName = \"Jane\"; // Erreur de compilation - propriété init-only\n```\n\n## Directives Using globales (C# 10.0+)\n\n```csharp\n// GlobalUsings.cs\nglobal using System;\nglobal using System.Collections.Generic;\nglobal using System.Linq;\nglobal using System.Threading.Tasks;\nglobal using Microsoft.Extensions.Logging;\nglobal using MyApp.Common.Extensions;\n\n// Maintenant ces usings sont disponibles dans tous les fichiers du projet\n```\n\n## Espaces de noms à portée de fichier (C# 10.0+)\n\n```csharp\n// Namespace traditionnel\nnamespace MyApp.Services\n{\n    public class UserService\n    {\n        // Implémentation\n    }\n}\n\n// Namespace à portée de fichier (C# 10)\nnamespace MyApp.Services;\n\npublic class UserService\n{\n    // Implémentation\n}\n```\n\n## Littéraux de chaîne bruts (C# 11.0+)\n\n```csharp\n// Chaîne traditionnelle avec séquences d'échappement\nstring json = \"{\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}\";\n\n// Chaîne verbatim\nstring jsonVerbatim = @\"{\"\"name\"\": \"\"John\"\", \"\"age\"\": 30}\";\n\n// Littéral de chaîne brut (C# 11)\nstring jsonRaw = \"\"\"\n                {\n                    \"name\": \"John\",\n                    \"age\": 30\n                }\n                \"\"\";\n\n// Exemple SQL\nstring sql = \"\"\"\n            SELECT u.Name, u.Email, p.Title\n            FROM Users u\n            INNER JOIN Posts p ON u.Id = p.AuthorId\n            WHERE u.IsActive = 1\n            ORDER BY p.CreatedAt DESC\n            \"\"\";\n```\n\n## Membres requis (C# 11.0+)\n\n```csharp\npublic class Person\n{\n    public required string FirstName { get; set; }\n    public required string LastName { get; set; }\n    public string? MiddleName { get; set; }\n    public int Age { get; set; }\n}\n\n// Usage\nvar person = new Person\n{\n    FirstName = \"John\",\n    LastName = \"Doe\",\n    Age = 30\n}; // MiddleName est optionnel\n\n// var invalidPerson = new Person { Age = 30 }; // Erreur de compilation - FirstName et LastName sont requis\n```\n\n## Motifs de liste (C# 11.0+)\n\n```csharp\nstatic string CheckList(int[] numbers) => numbers switch\n{\n    [] => \"Liste vide\",\n    [var single] => $\"Élément unique : {single}\",\n    [var first, var second] => $\"Deux éléments : {first}, {second}\",\n    [var first, .., var last] => $\"Plusieurs éléments, premier : {first}, dernier : {last}\",\n    [1, 2, 3] => \"Exactement 1, 2, 3\",\n    [1, .. var rest] => $\"Commence par 1, reste : [{string.Join(\", \", rest)}]\",\n    _ => \"Autre motif\"\n};\n```\n\n## Conseils de performance\n\n### Utiliser Span<T> pour des opérations efficaces en mémoire\n\n```csharp\nstatic void ProcessLargeArray(int[] data)\n{\n    // Au lieu de créer des sous-tableaux, utiliser Span<T>\n    var span = data.AsSpan();\n    var firstHalf = span[..(span.Length / 2)];\n    var secondHalf = span[(span.Length / 2)..];\n    \n    ProcessSpan(firstHalf);\n    ProcessSpan(secondHalf);\n}\n\nstatic void ProcessSpan(ReadOnlySpan<int> span)\n{\n    foreach (var item in span)\n    {\n        // Traiter sans allocation\n    }\n}\n```\n\n### Utiliser ValueTask pour les méthodes async critiques en performance\n\n```csharp\npublic async ValueTask<User> GetUserAsync(int id)\n{\n    // Si le résultat est mis en cache, retourner de manière synchrone sans allocation de Task\n    if (_cache.TryGetValue(id, out var cachedUser))\n    {\n        return cachedUser;\n    }\n    \n    // Sinon, effectuer l'opération asynchrone\n    var user = await _database.GetUserAsync(id);\n    _cache[id] = user;\n    return user;\n}\n```\n\n## Meilleures pratiques\n\n1. **Utilisez la correspondance de motifs** pour rendre le code plus lisible et concis\n2. **Tirez parti des records** pour les modèles de données immutables\n3. **Activez les types de référence nullable** pour une meilleure sécurité null\n4. **Utilisez les flux asynchrones** pour traiter de gros jeux de données\n5. **Préférez les propriétés init-only** pour les objets immutables\n6. **Utilisez les littéraux de chaîne bruts** pour le contenu de chaîne complexe\n7. **Marquez les membres requis** pour assurer une initialisation appropriée\n8. **Considérez les implications de performance** des nouvelles fonctionnalités\n\nCes fonctionnalités avancées peuvent considérablement améliorer la qualité de votre code, mais n'oubliez pas de les utiliser judicieusement selon vos cas d'usage spécifiques et les préférences de votre équipe."),
